// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json.Nodes;
using Campground.Shared.Registry;
using Campground.Shared.Storage;

namespace Campground.Shared.Emergency
{
    /// <summary>
    /// The emergency brake. When a Campground script breaks the web client, an admin can turn off every
    /// Campground plugin's browser side (or one plugin's) without the web client:
    /// <list type="bullet">
    /// <item>create an empty file <c>&lt;jellyfin data&gt;/campground/DISABLE</c> (all) or <c>DISABLE.&lt;pluginId&gt;</c>, or</item>
    /// <item>set the environment variable <c>CAMPGROUND_DISABLE=1</c> (or a comma list of plugin ids), or</item>
    /// <item>open the web client with <c>?campground=off</c> (that browser only; handled by campground.js).</item>
    /// </list>
    /// Server-side features keep running; only injection and the runtime stop. The dashboard toggle writes the
    /// same state file.
    /// </summary>
    internal static class EmergencyDisable
    {
        internal const string AllFile = "DISABLE";
        internal const string EnvVar = "CAMPGROUND_DISABLE";
        private const string StateFileName = "emergency.json";

        /// <summary>True when everything Campground is off.</summary>
        internal static bool IsCampgroundDisabled => Read().All;

        /// <summary>True when the given plugin (or everything) is off.</summary>
        internal static bool IsDisabled(string pluginId)
        {
            var s = Read();
            return s.All || s.Plugins.Contains(pluginId);
        }

        /// <summary>Snapshot for dashboards.</summary>
        internal static (bool All, IReadOnlyCollection<string> Plugins, string Source) Status()
        {
            var s = Read();
            return (s.All, s.Plugins, s.Source);
        }

        /// <summary>Turns everything (pluginId null) or one plugin off/on from the dashboard. Persists across restarts.</summary>
        internal static void Set(string? pluginId, bool disabled)
        {
            if (!CampgroundPaths.IsInitialized)
            {
                return;
            }

            // Every plugin's copy writes this one file. The registry is shared by all copies in the process, so a
            // lock object kept there serialises them where a static in each copy would not.
            var gate = CampgroundRegistry.Section("emergency").GetOrAdd("gate", _ => new object());
            lock (gate)
            {
                var file = new AtomicJsonFile(Path.Combine(CampgroundPaths.Root, StateFileName));
                var node = file.LoadNode() ?? new JsonObject();
                if (pluginId == null)
                {
                    node["all"] = disabled;
                }
                else
                {
                    var list = new HashSet<string>(StringComparer.Ordinal);
                    if (node["plugins"] is JsonArray existing)
                    {
                        foreach (var n in existing)
                        {
                            if (n is JsonValue v && v.TryGetValue<string>(out var s))
                            {
                                list.Add(s);
                            }
                        }
                    }

                    if (disabled)
                    {
                        list.Add(pluginId);
                    }
                    else
                    {
                        list.Remove(pluginId);
                    }

                    node["plugins"] = new JsonArray(list.OrderBy(x => x).Select(x => (JsonNode?)JsonValue.Create(x)).ToArray());
                }

                node["changedUtc"] = DateTime.UtcNow;
                file.SaveNode(node);
            }

            ClearCache();
            CampgroundEvents.Publish(EventNames.EmergencyDisabled, new { pluginId, disabled });
        }

        /// <summary>Forgets the cached read (tests, and Set).</summary>
        internal static void ClearCache()
        {
            lock (CacheGate)
            {
                _cached = null;
            }
        }

        private sealed record State(bool All, HashSet<string> Plugins, string Source);

        // Read() runs for every tag on every index.html and runtime.js request, so the answer is kept for a
        // few seconds. Keyed on the folder and the variable, so a different data folder never sees a stale one.
        private static readonly TimeSpan CacheFor = TimeSpan.FromSeconds(3);
        private static readonly object CacheGate = new();
        private static (State State, string Key, long Tick)? _cached;

        private static State Read()
        {
            var key = (CampgroundPaths.IsInitialized ? CampgroundPaths.Root : string.Empty) + "|" + Environment.GetEnvironmentVariable(EnvVar);
            var now = Environment.TickCount64;
            lock (CacheGate)
            {
                if (_cached is { } c && c.Key == key && now - c.Tick < CacheFor.TotalMilliseconds)
                {
                    return c.State;
                }
            }

            var fresh = ReadFromDisk();
            lock (CacheGate)
            {
                _cached = (fresh, key, now);
            }

            return fresh;
        }

        private static State ReadFromDisk()
        {
            var plugins = new HashSet<string>(StringComparer.Ordinal);
            var sources = new List<string>();
            var all = false;

            var env = Environment.GetEnvironmentVariable(EnvVar);
            if (!string.IsNullOrWhiteSpace(env))
            {
                sources.Add("environment");
                var trimmed = env.Trim();
                if (trimmed is "1" or "*" || trimmed.Equals("true", StringComparison.OrdinalIgnoreCase)
                    || trimmed.Equals("all", StringComparison.OrdinalIgnoreCase))
                {
                    all = true;
                }
                else
                {
                    foreach (var id in trimmed.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
                    {
                        plugins.Add(id);
                    }
                }
            }

            if (CampgroundPaths.IsInitialized)
            {
                try
                {
                    var root = CampgroundPaths.Root;
                    if (File.Exists(Path.Combine(root, AllFile)))
                    {
                        all = true;
                        sources.Add("file");
                    }

                    foreach (var f in Directory.EnumerateFiles(root, AllFile + ".*"))
                    {
                        // On Windows "DISABLE.*" also matches the bare DISABLE file, which has no id after the dot.
                        var fileName = Path.GetFileName(f);
                        if (fileName.Length > AllFile.Length + 1)
                        {
                            plugins.Add(fileName.Substring(AllFile.Length + 1));
                            sources.Add("file");
                        }
                    }

                    var state = new AtomicJsonFile(Path.Combine(root, StateFileName)).LoadNode();
                    if (state != null)
                    {
                        if (state["all"] is JsonValue a && a.TryGetValue<bool>(out var b) && b)
                        {
                            all = true;
                            sources.Add("dashboard");
                        }

                        if (state["plugins"] is JsonArray arr && arr.Count > 0)
                        {
                            foreach (var n in arr)
                            {
                                if (n is JsonValue v && v.TryGetValue<string>(out var id))
                                {
                                    plugins.Add(id);
                                }
                            }

                            sources.Add("dashboard");
                        }
                    }
                }
                catch (Exception)
                {
                    // Unreadable state never takes the server down; fail open (enabled).
                }
            }

            return new State(all, plugins, string.Join(",", sources.Distinct()));
        }
    }
}
